// Reads the names the settings markup carries (data attributes and option values) into model
// types. The markup is generated by the app, so an unknown name is a bug and fails loudly.
import { defaults, fields, presets, type NumericField, type PresetId } from './config.ts';
import type { BooleanSetting, ChoiceSetting } from './controls-view.ts';
import type { RoomItemType } from './room-actions.ts';
import { furnitureNames } from './room.ts';

export type LayoutPresetName = 'left' | 'front' | 'right';

const LAYOUT_PRESETS: readonly string[] = ['left', 'front', 'right'] satisfies LayoutPresetName[];
const OPENING_TYPES: readonly string[] = ['door', 'window', 'wardrobeAccess'];

const isOwnKey = <T extends object>(
  object: T,
  key: string | undefined,
): key is Extract<keyof T, string> => key !== undefined && Object.hasOwn(object, key);

export function numericField(key: string | undefined): NumericField {
  if (!isOwnKey(fields, key)) throw new Error(`Unknown numeric setting: ${key}`);
  return key;
}

export function booleanSetting(key: string | undefined): BooleanSetting {
  if (!isOwnKey(defaults, key) || typeof defaults[key] !== 'boolean')
    throw new Error(`Unknown toggle: ${key}`);
  return key as BooleanSetting;
}

export function choiceSetting(key: string | undefined): ChoiceSetting {
  if (!isOwnKey(defaults, key) || typeof defaults[key] !== 'string')
    throw new Error(`Unknown choice: ${key}`);
  return key as ChoiceSetting;
}

export function presetId(value: string | undefined): PresetId {
  if (!isOwnKey(presets, value)) throw new Error(`Unknown preset: ${value}`);
  return value;
}

export function roomItemType(value: string | undefined): RoomItemType {
  if (value !== undefined && OPENING_TYPES.includes(value)) return value as RoomItemType;
  if (!isOwnKey(furnitureNames, value)) throw new Error(`Unknown room item: ${value}`);
  return value;
}

export function layoutPresetName(value: string): LayoutPresetName {
  if (!LAYOUT_PRESETS.includes(value)) throw new Error(`Unknown layout: ${value}`);
  return value as LayoutPresetName;
}
